function UIActivityEntryWelfareDialog:Awake()
    self.rewardButton5 = self.Skin.transform.parent.parent:Find("RewardButton/BtnReward1")
    self.rewardButton7 = self.Skin.transform.parent.parent:Find("RewardButton/BtnReward2")
    self.rewardButton30 = self.Skin.transform.parent.parent:Find("RewardButton/BtnReward3")
    self.rewardButton35 = self.Skin.transform.parent.parent:Find("RewardButton/BtnReward4")
    SetButtonAction(self.ButtonClose, function()
        if isNull(self.data) then
            Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)        
            UIModule.BackDialog()
            return
        end
        -- 完成入职福利签到， 解锁每日签到
        local isDraw =  self.isDraw
        if self.data.totalDrawNum >= #self.data.rewards  and isDraw then
            self.data.status = 0 
            UIModule.CloseDialog(self.controller)
            ---@type PlayerComponent
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            local currentDayId = os.date("%Y%m%d", playerComponent:GetPlayerDojo():GetServerTime())
            CfUtils.WriteLocalData("Start_Contact_Sign" , currentDayId)
