            return
        end
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)
        CfUtils.StartCoroutineWithBlocker(function ()
            KTool.SetActive(self.controller , false)
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.2))
            UIModule.BackDialog()
        end)
    end)
    SetButtonAction(self.EmptyClose, function()
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)
        UIModule.BackDialog()
    end)
    SetButtonAction(self.rewardButton5, function()
        self:FreshSpecDay(Day5 - 1)
    end)
    SetButtonAction(self.rewardButton7, function()
        self:FreshSpecDay(Day7 - 1)
    end)
