            local vo = goodsConfMgr:GetGoodsVoById(goodsId)
            local row = goodsConfMgr:GetJumpModuleRow(417)
            goodsConfMgr:ExecuteJump(row, vo)
        end)
    end
end

local SecondPerMin = 60
local SecondPerHour = 3600  -- 60*60
local SecondPerDay = 86400 -- 24*60*60
local NumberTheme = "<color=#000000><size=22>%d</size></color>"
local NumberNoSizeColor = "%d"
local function FormatTime(second, theme)
    if second < SecondPerMin then
        return localize("小于一分钟")
    else
        if theme == nil or not theme then
            theme = NumberTheme
        else
            theme = NumberNoSizeColor
        end
        local result = {}
        if second > SecondPerDay then
            table.insert(result, string.format(theme, math.floor(second / SecondPerDay)))
            if GameUtils.isZmFunction() then
                table.insert(result, string.format('%s ', localize("天")))
            else
                table.insert(result, localize("天"))
            end
            second = second % SecondPerDay
        end

        if second > SecondPerHour then
            table.insert(result, string.format(theme, math.floor(second / SecondPerHour)))
            if GameUtils.isZmFunction() then
                table.insert(result, string.format('%s ', localize("时")))
            else
                table.insert(result, localize("时"))
            end
            second = second % SecondPerHour
        end

        if second > SecondPerMin then
            table.insert(result, string.format(theme, math.floor(second / SecondPerMin)))
            table.insert(result, localize("分"))
        end

        return table.concat(result)
    end

end

function UIActivityEntryWelfareDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.Broadcast(Constants.EventNames.MainHomeRoleActive, { isShow = false })
        coroutine.yield()
        self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id, Elapsed)
            self.data.residueSecond = checkInt(self.data.residueSecond) - Elapsed
            if self.data.residueSecond <= 0 then
                ---时间结束了
                self.isFinish = true
            else
                if checkInt(self.data.residueSecond) > 0 then
                    CfUtils.FillText(self.TextTime, FormatTime(checkNumber(self.data.residueSecond), true))
                end
            end
        end, CountDownTime, false, true)
        if checkNumber(self.data.totalDrawNum) > 20 then
            --self.RewardList:MovePanelToItemByIndex(checkNumber(20))
            self.RewardList:MovePanelToItemByIndex(checkNumber(self.data.totalDrawNum))
        end
    end))
    return coWait
end

function UIActivityEntryWelfareDialog:MovePanelToItemByIndex(ind)
    if checkNumber(ind) > 0 then
        local targetIndex = ind
        local rewardItemData = self.ListView:GetItemPrefabConfData('Cell')
        local rewardItemHeight = rewardItemData.mItemPrefab.transform.sizeDelta.y
        local rewardListItemH = rewardItemHeight + rewardItemData.mPadding
        local containerH = (targetIndex * rewardListItemH) - rewardItemData.mPadding
        CoYield()
        logs('>>> 5', self.ListView.ViewPortSize, self.ListView.ViewPortHeight)
        logs('>>> 6', containerH - self.ListView.ViewPortHeight)
        self.ListView.ContainerTrans.anchoredPosition = Vector2(0, containerH - self.ListView.ViewPortHeight)
    end
end

