function UIActivityEntryWelfareDialog:FreshList()
    local count = #self.data.rewards
    local isShowList = count > 0
    local ScrollView = self.RewardList

    if not isShowList then
        return
    end
    if self._isInitList then
        GameUtils.ReloadData(ScrollView, count)
    else
        self._isInitList = true
        ScrollView:InitGridView(count, Bind(self, self.OnGetItemByIndex))
    end
end

function UIActivityEntryWelfareDialog:OnGetItemByIndex(listView, idx)
    if idx < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    ---@type UIActivityEntryWelfareCellNode
    local nodeEnv = CfUtils.GetLuaScr(cell, CellEnvPath)
    if isNull(nodeEnv) then
        return nil
    end
    local index = idx + 1
    local data = self.data.rewards[index]
    nodeEnv:FreshUI(data, Bind(self, self.OnClickCellAction), index, checkNumber(self.data.totalDrawNum), checkNumber(self.data.drawStatus))
    return cell
end

---OnClickCellAction
---gameObject UnityEngine.GameObject
---点击事件
---@param data table
function UIActivityEntryWelfareDialog:OnClickCellAction(data , gameObject)
    --print('--->>', table.dump(self.data, false, 2), data.id)
    local totalDrawNum = checkNumber(self.data.totalDrawNum)
    if (not (checkNumber(data.id) <= totalDrawNum)) and  checkNumber(self.data.drawStatus) == 0 and checkNumber(data.id) == (totalDrawNum + 1) and (not self.isFinish) then
        ---今天的奖励未领取的时候, 且只能领取当前天的奖励
        GameUtils.Request(Interfaces.OverseaActivityEntryWelfareDraw, {}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                local responseData = checkTable(response.data)
                self.data.drawStatus = 1
                self.data.totalDrawNum = checkNumber(self.data.totalDrawNum) + 1
                self.isDraw = true
                ---@type PlayerComponent
                local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                ---@type PlayerDojo
                local playerDojo = playerComponent.playerDojo
                playerDojo.entryWelfareInfo.drawStatus = 1
                playerDojo.entryWelfareInfo.totalDrawNum = self.data.totalDrawNum
                if isSet(responseData, "rewards") then
                    if table.count(checkTable(responseData.rewards)) > 0 then
                        local skinId = 0 
                        for k, v in pairs(responseData.rewards) do
                            local goodsType = GoodsUtils.GetIdType(v.goodsId)
                            if goodsType == Constants.IDType.CardSkin then
                                skinId = v.goodsId 
                                break
                            end    
                        end
                        GoodsUtils.DrawRewards(checkTable(responseData.rewards), true)
                        ---@type GachaponUtils
                        local GachaponUtils = import('Game.Gachapon.GachaponUtils')
                        if skinId > 0 then
                            GachaponUtils.OpenDialogAction(Constants.UITypeIds.CommonCardDisplayDialog, {
                                cardInfo   = { { goodsId =  skinId } },     
                                isSkin = true       , 
                                onCloseCb  = function()
                                    UIModule.CloseDialogById(Constants.UITypeIds.CommonCardDisplayDialog)
                                    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = clone(responseData.rewards) } })
                                end,
                            }, nil)
                        else 
                            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = clone(responseData.rewards) } })
                        end
                        
                    end
                end
                GameUtils.SetRedPointNum(Constants.RedPointConst.OverseaEntryWelfare, checkNumber(playerDojo.entryWelfareInfo.drawStatus) == 0 and 1 or 0)
                GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.OverseaEntryWelfare)
                self:FreshUI() --刷新界面
            end
        end)
        return
    end
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.rewards[1].goodsId)
    GameUtils.ShowCommonTipsBoard(gameObject, vo.name, vo.desc, vo.quality, vo.id, true)   
    -- local totalDrawNum = checkNumber(self.data.totalDrawNum)
    -- if checkNumber(data.id) <= totalDrawNum then
    --     GameUtils.Toast(localize('当前奖励已领取'))
    -- else
       
    --     if checkNumber(self.data.drawStatus) == 1 then
    --         GameUtils.Toast(localize('今天已赠送，明天再来'))
    --     elseif checkNumber(data.id) > totalDrawNum then
    --         GameUtils.Toast(localize('不能领取当前奖励'))
    --     end
    -- end
end
