function UIActivityEntryWelfareDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)
        ---@type CardProgressionControllerRole
        self.roleController_ = CardProgressionUtils.GetRoleControllerEnv()

        -- save old role state data
        if not isNull(self.roleController_) then
            self.roleController_:FreshCameraStateByParams({CardProgressionConstants.CameraState.ShowRoleOnUI, CatBallCameraPosition , CatBallCameraRotation, false, true})

        end
        coroutine.yield()
        local isFinish = false
        GameUtils.Request(Interfaces.OverseaActivityEntryWelfare, {}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                self.data = checkTable(response.data)
                ---@type PlayerComponent
                local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                ---@type PlayerDojo
                local playerDojo = playerComponent.playerDojo
                playerDojo.entryWelfareInfo.residueDay = checkNumber(self.data.residueDay)
                playerDojo.entryWelfareInfo.drawStatus = checkNumber(self.data.drawStatus)
                playerDojo.entryWelfareInfo.status = checkNumber(self.data.status)
                GameUtils.SetRedPointNum(Constants.RedPointConst.OverseaEntryWelfare, checkNumber(playerDojo.entryWelfareInfo.drawStatus) == 0 and 1 or 0)
                GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.OverseaEntryWelfare)
                isFinish = true
            end
        end)
        while not isFinish do
            coroutine.yield(Yielders.EndOfFrame)
        end
        self:FreshUI()
    end))
    return coWait
end

function UIActivityEntryWelfareDialog:FreshInvitation()
    if isNotNull(self.goodsListScr) then
        return
    end
    ---@type EntryWelfareArgVo
    local EntryWelfareArgVo = CfUtils.GetCfVo(AutoIds.IdSetting6304 ,"EntryWelfareArgVo" , 3)
    local rewards = EntryWelfareArgVo.rewardData
    ---@type CommonGoodsListLight
    self.goodsListScr = CfUtils.GetLuaScr(self.CommonGoodsListLight, "Game.Behaviours.CommonGoodsListLight")
    self.goodsListScr:FreshBaseUI(rewards)
end

function UIActivityEntryWelfareDialog:RemoveTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
end

function UIActivityEntryWelfareDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:RemoveTimeDown()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIActivityEntryWelfareDialog